(7342833, 1147058, 156466, '<td valign="top">In a photo where lines are key the verticals in the center of this (that all the leading lines are leading to) are all leaning hard left.</td>', 'In a photo where lines are key the verticals in the center of this (that all the leading lines are leading to) are all leaning hard left.', '2015-04-16 09:42:13.000000', NULL, 1),
(7342834, 1147125, 156466, '<td valign="top">Could do without the letter box.  Nice lines, but I don''t know that the lead as I wouldn''t consider the tiled floor the subject.</td>', 'Could do without the letter box.  Nice lines, but I don''t know that the lead as I wouldn''t consider the tiled floor the subject.', '2015-04-16 09:44:00.000000', NULL, 1),
(7342835, 1147024, 156466, '<td valign="top">Again, nice lines, but what do they "lead" to?</td>', 'Again, nice lines, but what do they "lead" to?', '2015-04-16 09:44:33.000000', NULL, 1),
(7342836, 1147111, 156466, '<td valign="top">I''d pull the subject in from the corner a little more - lines lead too far.</td>', 'I''d pull the subject in from the corner a little more - lines lead too far.', '2015-04-16 09:45:28.000000', NULL, 1),
