(7342843, 1146244, 156466, '<td valign="top">For me this has a lot of wasted frame to the right and not enough room at the top.  Perhaps a different crop.</td>', 'For me this has a lot of wasted frame to the right and not enough room at the top.  Perhaps a different crop.', '2015-04-16 09:55:42.000000', NULL, 1),
(7342847, 1146338, 156466, '<td valign="top">As many lines distracting me as there are leading me.  If the horizontals were actually horizontal they wouldn''t distract from the actual leading lines.  Nice shot otherwise - just needs some perspective correction with the horizontals.</td>', 'As many lines distracting me as there are leading me.  If the horizontals were actually horizontal they wouldn''t distract from the actual leading lines.  Nice shot otherwise - just needs some perspective correction with the horizontals.', '2015-04-16 09:59:35.000000', NULL, 1),
